def largest_prime_factor(n):
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
    return n

def modular_sum(nums, m, target_sum):
    n = len(nums)
    dp = [[False] * (target_sum + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = True

def modular_sum(arr, n, m):
    if n == 0:
        return False
    if m == 0:
        return True
    if arr[n-1] == 0:
        return modular_sum(arr, n-1, m)
    return modular_sum(arr, n-1, m) or modular_sum(arr, n-1, m-arr[n-1])

def find_closest_elements(numbers):
    numbers.sort()
    min_diff = float('inf')
    closest_pair = None
    for i in range(len(numbers) - 1):
        diff = numbers[i+1] - numbers[i]
        if diff < min_diff:
            min_diff = diff
            closest_pair = (numbers[i], numbers[i+1])
    return closest_pair

def recursive_list_sum(lst):
    total = 0
    for i in lst:
        if isinstance(i, list):
            total += recursive_list_sum(i)
        else:
            total += i
    return total

import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def words_in_sentence(sentence):
    words = sentence.split()
    prime_words = []
    for word in words:
        if is_prime(len(word)):
            prime_words.append(word)
    return " ".join(prime_words)

def get_lcm(nums):
    lcm = 1
    for num in nums:
        lcm = lcm * num // math.gcd(lcm, num)
    return lcm

def get_lcm(arr):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    lcm = arr[0]
    for i in range(1, len(arr)):
        lcm = lcm * arr[i] // gcd(lcm, arr[i])
    return lcm

def magic_square_test(square):
    n = len(square)
    if any(len(row) != n for row in square):
        return False  # Not a square matrix

    # Calculate the sum of the first row to use as a reference
    target_sum = sum(square[0])

    # Check rows
    for row in square:
        if sum(row) != target_sum:
            return False

    # Check columns
    for col in range(n):
        if sum(square[row][col] for row in range(n)) != target_sum:
            return False

    # Check diagonals
    if sum(square[i][i] for i in range(n)) != target_sum:
        return False
    if sum(square[i][n-1-i] for i in range(n)) != target_sum:
        return False

    return True

